# mystery_box/main.py
import random
from utils import generate_code
from input_utils import get_valid_guess
from feedback import check_guess

def play_game():
    code = generate_code()
    attempts = 5
    print("Welcome to 'Mystery Box'!")
    print("You have 5 attempts to guess a 3-digit code between 100 and 999.")

    while attempts > 0:
        guess = get_valid_guess()
        result = check_guess(code, guess)
        if result == "Correct":
            print("🎉 Congratulations! You've cracked the code!")
            break
        else:
            print(result)
            attempts -= 1
            if attempts == 0:
                print(f"❌ Out of attempts! The code was {code}. Better luck next time!")

if __name__ == "__main__":
    play_game()
```

